import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="قرارات متفرقة / الدراسات العليا"
save("0286",N,[
("rule",[1],"قرار مجلس العمداء (شهادة الدكتوراة، 2007/2008)","طلب مجلس العمداء مخاطبة الجامعات الأردنية لتعديل تعليمات منح شهادة الدكتوراة وتطبيق شروط اعتباراً من العام الجامعي 2007/2008، وهي: اجتياز امتحان شامل، وإتقان لغة أجنبية (كالتوفل بحد أدنى 500 علامة أو ما يعادله من الامتحانات الفرنسية أو الألمانية أو غيرها) كشرط قبول قبل الالتحاق، وتوفير لجنة ممتحنين يشارك فيها ممتحنان من خارج الجامعة لتقييم الرسالة وتقديم تقريرين مكتوبين قبل المناقشة، ونشر (أو قبول نشر) بحثين في مجلات دولية محكمة للتخصصات العلمية وفي مجلات محلية أو عربية إقليمية محكمة للتخصصات الإنسانية كمتطلب للتخرج، وتكليف اللجنة الأكاديمية بالتحقق من تطبيق البنود (1-4) للتوصية بمنح الشهادة.",
 "ما الشروط التي قرر مجلس العمداء تطبيقها على الدكتوراة اعتباراً من 2007/2008؟","كم بحثاً يجب نشره للتخرج في الدكتوراة وما حد التوفل المطلوب كشرط قبول؟","شو شروط الدكتوراة من مجلس العمداء بخصوص الامتحان الشامل والنشر والممتحنين الخارجيين؟"),
("rule",[1],"قرار تأكيد اجتياز التوفل (جدول)","طلب من عمادات الدراسات العليا التأكيد على الراغبين في الالتحاق ببرامج الدراسات العليا بضرورة اجتياز امتحان التوفل أو ما يعادله حسب جدول: TOEFL Paper 500، TOEFL Computer 173، IELTS 5.",
 "ما العلامات المعادلة للتوفل المطلوبة للالتحاق بالدراسات العليا حسب الجدول (ورقي وحاسوبي وIELTS)؟","كم علامة IELTS تقابل 500 توفل ورقي في قبول الدراسات العليا؟","كم لازم أجيب بالـ IELTS والتوفل الحاسوبي عشان أنقبل بالدراسات العليا؟"),
("rule",[1],"قرار مجلس التعليم العالي (اللغة الإنجليزية، تخصصات الإنجليزية)","قرر مجلس التعليم العالي أن العلامة المعتمدة في التوفل للتخصصات التي تندرج تحت مظلة اللغة الإنجليزية (الأدب، الترجمة، الإنجليزي التطبيقي، اللغويات، أساليب التدريس) هي 550 أو ما يعادلها، لجميع الطلبة بغض النظر عن الكلية التي يتبع لها التخصص.",
 "كم علامة التوفل المطلوبة لتخصصات اللغة الإنجليزية كالأدب والترجمة في الدراسات العليا؟","هل علامة التوفل لتخصصات الإنجليزية تختلف حسب الكلية؟","شو علامة التوفل لتخصص الترجمة بالماجستير؟"),
("rule",[1],"قرار مجلس التعليم العالي (الامتحان الوطني للغة الإنجليزية)","وافق مجلس التعليم العالي على تعليمات الامتحان الوطني للغة الإنجليزية لطلبة الدراسات العليا، وعلى السماح للطلبة الملتحقين حالياً في برامج الدراسات العليا ولم يستكملوا شروط النجاح بامتحانات التوفل بالتقدم للامتحان الوطني للإنجليزية بعد دراسة مادتين استدراكيتين باللغة الإنجليزية تحددها الجامعة.",
 "ماذا يفعل طالب الدراسات العليا الذي لم ينجح في التوفل حسب تعليمات الامتحان الوطني للإنجليزية؟","كم مادة استدراكية يدرسها قبل التقدم للامتحان الوطني للغة الإنجليزية؟","ما اللي بصير إذا ما نجحت بالتوفل وأنا مسجل ماجستير؟"),
("rule",[1],"قرار مجلس التعليم العالي (طلبة الماجستير غير الناجحين في التوفل)","وافق مجلس التعليم العالي على السماح لطلبة الماجستير الذين لم يحققوا النجاح (مرتين على الأقل) في التوفل بعلامة 500 أو ما يعادله بدراسة مساقات في اللغة الإنجليزية والنجاح فيها بدلاً عن التوفل: الحاصلون على 400-499 يدرسون مساق مستوى (2) في الإنجليزية، والحاصلون على 399 فما دون يدرسون مساقين مستوى (1) و(2). وتشكل لجنة مختصة لوضع محتوى مساقي الإنجليزية المنوي تدريسهما لطلبة الماجستير، ويعقد امتحان موحد للطلبة المعنيين في المستوى (2) في مراكز اللغات (الأردنية واليرموك ومؤتة والهاشمية). ولا يعتبر اجتياز مساقات الإنجليزية من ضمن المدة القصوى لنيل الماجستير.",
 "ما البديل عن التوفل لطلبة الماجستير الذين رسبوا فيه مرتين على الأقل؟","كم مساقاً إنجليزياً يدرس من حصل على 400-499 ومن حصل على 399 فما دون في التوفل؟","هل تحسب مساقات الإنجليزية من المدة القصوى للماجستير؟"),
("rule",[1],"قرار مجلس التعليم العالي (الكفاءة الجامعية للمفاضلة)","وافق مجلس التعليم العالي على إدخال نتائج امتحان الكفاءة الجامعية كأحد شروط المفاضلة للقبول في برامج الدراسات العليا في الجامعات الأردنية إضافة إلى الشروط الأخرى، اعتباراً من الفصل الأول للعام الجامعي 2006/2007.",
 "هل تدخل نتيجة امتحان الكفاءة الجامعية في المفاضلة للقبول بالدراسات العليا؟","من أي عام جامعي يعتمد امتحان الكفاءة الجامعية كشرط مفاضلة في الدراسات العليا؟","امتحان الكفاءة الجامعية بيأثر على قبولي بالماجستير؟"),
("rule",[2],"قرار مجلس العمداء (2012) أوائل الخريجين","تضمنت قرارات مجلس العمداء: الإيقاف المبدئي لتعيين الأوائل من خريجي البكالوريوس كمساعدي بحث وتدريس تمهيداً للإيفاد، والتزام كلية الدراسات العليا بمنح خريجي الجامعة الأوائل الذين يقبلون في الماجستير منحاً تدريسية وفق ضوابط المنح التدريسية المعدلة، وإرسال من يقع عليه الاختيار من حملة البكالوريوس بتقدير جيد جداً ومن أوائل الدرجة من خارج الجامعة المتقدمين في بعثات دراسية وفق حاجة الجامعة، وإعطاء أوائل خريجي الكليات والأقسام التي ليس فيها برامج ماجستير فرصة للقبول في الماجستير والدكتوراه إن وجدت حاجة ماسة لذلك.",
 "ما قرارات مجلس العمداء بشأن أوائل خريجي البكالوريوس والمنح التدريسية للماجستير؟","هل يعطى أوائل خريجي الأقسام التي ليس فيها ماجستير فرصة للقبول بالدراسات العليا؟","كيف بتعامل الجامعة أوائل الخريجين من ناحية المنح والإيفاد؟"),
("rule",[2],"قرار مجلس العمداء (استثناء الطب والتمريض)","يستثنى من قرار عدم قبول من يعمل بوظيفة مساعد بحث وتدريس في الجامعة في برنامج الماجستير أو الدكتوراه كليتا الطب والتمريض، نظراً لطبيعة عمل الكليتين واحتياجاتهما والطلبة المرسلين للإيفاد والتدريب الخاص بكلية الطب وفق ما يقترح عميد كلية الطب أو التمريض وتعليماتها الخاصة.",
 "هل يشمل منع قبول مساعد البحث والتدريس في الماجستير كليتي الطب والتمريض؟","لماذا استثنيت كليتا الطب والتمريض من قرار قبول مساعدي البحث والتدريس؟","أنا مساعد بحث بكلية الطب، بقدر أنقبل ماجستير؟"),
("rule",[2],"قرار مجلس العمداء (منح وزارة الصحة)","تقدم الجامعة خمس منح لكوادر وزارة الصحة في برامج الدراسات العليا بالجامعة، على أن يحقق المرشحون لهذه المنح الشروط اللازمة للقبول في كلية الدراسات العليا والشروط الخاصة في البرامج المختلفة.",
 "كم منحة تقدمها الجامعة لكوادر وزارة الصحة في الدراسات العليا؟","ما شروط المرشحين لمنح وزارة الصحة في الدراسات العليا؟","في منح لموظفي وزارة الصحة بالدراسات العليا؟"),
("rule",[2],"كتاب وزارة التعليم العالي (معادلة الشهادات غير الأردنية)","وثيقة المعادلة الصادرة عن وزارة التعليم العالي تشير إلى أن الشهادة لا تحتاج إلى معادلة (التصديق على الشهادات العلمية الصادرة عن مؤسسات التعليم العالي غير الأردنية، العربية والأجنبية، لا يعني معادلة هذه الشهادات) وتكون هي الوثائق الأساسية المطلوبة عند التقدم بطلب للالتحاق بالدراسات العليا للإيفاد والتدريب الخاص والتجسير.",
 "هل يغني تصديق الشهادة غير الأردنية عن معادلتها عند التقدم للدراسات العليا؟","ما الوثيقة المطلوبة من الوزارة بخصوص الشهادات غير الأردنية عند التقدم للدراسات العليا؟","شهادتي من جامعة عربية مصدقة، بكفي عن المعادلة؟"),
("rule",[2],"قرار مجلس العمداء (2004/7/26) تعديل المراقبة","عدل مجلس العمداء قراره السابق بمنع طلبة الماجستير (بمن فيهم الجرايات) من المراقبة على الامتحانات أو دخول الامتحان في كليات الجامعة، بحيث يجوز الاستفادة من طلبة الدراسات العليا الحاصلين على الجرايات في حالة الضرورة القصوى للاحتياجات، ضمن ضوابط معينة: وجود عضو هيئة تدريس في الامتحان، وعدم مراقبة الطالب في تخصصه، وأن يكون عميد الكلية المعني قد حدد هؤلاء الطلبة، وألا يسمح لهم بالاشتراك في تقييم الطلبة وتصحيح أوراق الامتحان.",
 "متى يجوز الاستفادة من طلبة الدراسات العليا الحاصلين على جرايات في مراقبة الامتحانات؟","ما ضوابط مراقبة الجرايات للامتحانات؟","بقدر أراقب امتحان وأنا طالب ماجستير جراية؟"),
("rule",[2],"قرار مجلس التعليم العالي (الفصول الصيفية)","وافق مجلس التعليم العالي على عدم طرح برامج الدراسات العليا على الفصول الصيفية فقط في الجامعات الأردنية الرسمية والخاصة وأي مؤسسة للتعليم العالي أو فرع لها يتم إنشاؤه في المملكة، واعتبار تسجيل أي طالب لاغياً.",
 "هل يمكن أن تطرح برامج الدراسات العليا في الفصول الصيفية فقط؟","ماذا يحدث لتسجيل الطالب إذا كان البرنامج مطروحاً في الصيفي فقط؟","في برنامج ماجستير صيفي بس؟"),
("rule",[2],"أسس مجلس التعليم العالي لبرامج الدراسات العليا في مؤسسات التعليم العالي الهاشمية (أولاً-1 إلى 3)","من الأسس: الجامعة التي بدأت بتدريس برنامج ماجستير أو خرجت طلبة منه تستمر بذلك إلا إذا منعتها هيئة اعتماد مؤسسات التعليم العالي أو سحبت ترخيص البرنامج. ولا يجوز لأي جامعة البدء بأي برنامج ماجستير إلا بعد أن تكون قد خرجت خمس دفعات من برنامج البكالوريوس المماثل، شريطة الحصول على ترخيص للبرنامج وتحقيق معايير الاعتماد. وكل جامعة أخذت ترخيصاً لبرنامج ماجستير ولم تستقبل طلبة فيه حتى تاريخ معين يعتبر ترخيصها لاغياً.",
 "متى يجوز لجامعة البدء ببرنامج ماجستير جديد حسب أسس مجلس التعليم العالي؟","ماذا يحدث لترخيص برنامج الماجستير الذي لم يستقبل طلبة حتى التاريخ المحدد؟","كم دفعة بكالوريوس لازم تخرج الجامعة قبل ما تفتح ماجستير؟"),
("rule",[3],"أسس مجلس التعليم العالي لبرامج الدراسات العليا (أولاً-4 إلى 7)","يستثنى من البندين (1، 2) أعلاه التخصصات التي يمكن البدء ببرنامج ماجستير فيها دون الحاجة لبكالوريوس في نفس الموضوع مثل دراسات المرأة والدراسات الاستراتيجية، وتعامل كل حالة على حدة. وفي جميع الأحوال تطبق على الجامعات الشروط الصادرة عن المجلس وشروط هيئة اعتماد مؤسسات التعليم العالي. ولا يجوز لجامعة أجنبية معترف بها فتح برامج دراسات عليا في المملكة إلا بالاشتراك مع جامعة أردنية. ويستمر منع استحداث برامج الدكتوراه في الجامعات الرسمية والخاصة حتى إشعار آخر، ويستثنى البرامج الوطنية المشتركة.",
 "هل يمكن فتح برنامج دكتوراه جديد في الجامعات الأردنية حسب أسس مجلس التعليم العالي؟","متى يجوز لجامعة أجنبية فتح برامج دراسات عليا في الأردن؟","ما التخصصات التي تستثنى من شرط وجود بكالوريوس مماثل لفتح الماجستير؟"),
("rule",[3],"أسس مجلس التعليم العالي لبرامج الدراسات العليا (ثانياً)","يحق الالتحاق ببرامج الدراسات العليا لمن حصل على البكالوريوس بتقدير لا يقل عن جيد (ماجستير ودكتوراه)، ويقبل حامل البكالوريوس بتقدير مقبول في الماجستير شريطة دراسة 3 مواد من الماجستير (خلال الفصل الأول) والنجاح بمعدل لا يقل عن 70% وبمعدل تراكمي لا يقل عن 75%، وتحسب في خطته. ومن حصل على الدبلوم العالي بتقدير لا يقل عن جيد جداً يقبل في الماجستير. ويشترط ألا تزيد نسبة المقبولين بتقدير مقبول عن 20% من إجمالي المقاعد المخصصة في كل تخصص. ومن حصل على الماجستير بتقدير لا يقل عن جيد يحق له الالتحاق بالدرجة الأعلى.",
 "ما الشروط التي يحق بموجبها الالتحاق ببرامج الدراسات العليا حسب أسس مجلس التعليم العالي؟","ما أقصى نسبة للمقبولين بتقدير مقبول في الماجستير؟","حامل الدبلوم العالي بجيد جداً، بقدر ينقبل ماجستير؟"),
("rule",[3],"أسس مجلس التعليم العالي لبرامج الدراسات العليا (ثانياً-6، 7)","كل من حصل على البكالوريوس بتقدير مقبول والماجستير بتقدير لا يقل عن جيد يحق له الالتحاق ببرامج الدكتوراه. وكل من سمح له بالقبول بنظام الانتساب وكان قد حصل على البكالوريوس بالانتساب بتقدير لا يقل عن جيد يسمح له الالتحاق ببرنامج الدكتوراه.",
 "هل يحق لحامل بكالوريوس مقبول وماجستير جيد الالتحاق بالدكتوراه؟","شروط التحاق خريج الانتساب بالدكتوراه؟","بكالوريوس مقبول وماجستير جيد، بقدر أكمل دكتوراه؟"),
("rule",[3],"أسس مجلس التعليم العالي لبرامج الدراسات العليا (ثالثاً)","يشترط على الراغب في الالتحاق بالدراسات العليا تقديم ما يثبت نجاحه في امتحان مقدرة في لغة أجنبية (التوفل أو IELTS أو غيرها). والحد الأدنى: التوفل ITP بعلامة لا تقل عن 500 أو ما يعادلها للتخصصات العلمية، و400 أو ما يعادلها للتخصصات الإنسانية، و550 لتخصصات اللغة الإنجليزية كافة وتخصصات البرامج المشتركة مع الجامعات الأجنبية، من مراكز اللغات المعتمدة في الجامعات الأردنية أو مركز أميديست (AMIDEAST). والتوفل iBT بعلامة لا تقل عن 61 للتخصصات العلمية، و32 للإنسانية، و79 لتخصصات الإنجليزية والبرامج المشتركة مع الجامعات الأجنبية. ويستثنى الطلبة غير الناطقين بالعربية من إثبات مقدرتهم على التحدث بالعربية بشرط تقديم إثبات على مقدرتهم على التحدث بالإنجليزية.",
 "ما الحد الأدنى للتوفل ITP وiBT للتخصصات العلمية والإنسانية وتخصصات اللغة الإنجليزية في الدراسات العليا؟","من يستثنى من إثبات المقدرة في اللغة العربية عند الالتحاق بالدراسات العليا؟","كم علامة التوفل iBT لتخصص علمي وإنساني؟"),
("rule",[4],"أسس مجلس التعليم العالي لبرامج الدراسات العليا (ثالثاً-2، رابعاً، خامساً، سادساً)","الطلبة الذين يحصلون على التوفل للتقدم للماجستير يستطيعون الاستفادة من نفس الشهادة عند تقدمهم لبرامج الدكتوراه. وتطبق هذه القرارات على الطلبة المقبولين اعتباراً من الفصل الأول للعام الجامعي 2010/2011 إلا إذا كان هناك طلبة حاصلون على إمتحان قدرات لغوية ساري المفعول فيمكن قبولهم على الفصل الثاني 2009/2010، وفي جميع الأحوال تطبق القرارات الخاصة بالتوفل على الطلبة الموجودين حالياً على مقاعد الدراسة إذا كانوا سيستفيدون منها. ولا يسمح لطلبة الدبلومات المهنية بالالتحاق ببرامج الدراسات العليا.",
 "من أي عام تطبق قرارات اللغة الأجنبية والقبول الجديدة للدراسات العليا؟","هل أستفيد من نفس شهادة التوفل للماجستير في طلب الدكتوراه؟","هل يسمح لخريجي الدبلومات المهنية بالدراسات العليا؟"),
("rule",[4],"قرار مجلس الأمناء (الماجستير في كلية طب الأسنان، Bench Fees)","حدد مجلس الأمناء الرسوم الإضافية (رسوم استعمال المواد والأجهزة والمختبرات Bench Fees) لطلبة الماجستير في كلية طب الأسنان: للأردنيين 1500 دينار أردني للفصل الواحد (الأول أو الثاني أو الثالث)، ولغير الأردنيين 5000 دولار أمريكي للفصل الواحد. وتكون الرسوم المعتمدة 60 ديناراً للساعة المعتمدة الواحدة للأردنيين و150 دولاراً أمريكياً لغير الأردنيين (عُدلت لاحقاً إلى 250 دولاراً من العام 2012/2013). وبرنامج الماجستير 45 ساعة معتمدة ومدته 3 سنوات.",
 "كم رسوم Bench Fees لطلبة ماجستير طب الأسنان الأردنيين وغير الأردنيين؟","كم عدد ساعات ماجستير طب الأسنان ومدته وسعر الساعة؟","كم رسوم الساعة والبنش فيز لماجستير طب الأسنان؟"),
("rule",[4,5],"قرار مجلس الأمناء (2012/7/5) رسوم غير الأردنيين","قرر مجلس الأمناء تعديل الرسوم الجامعية لبرامج الدراسات العليا (الدبلوم والماجستير والاختصاص العالي) للطلبة غير الأردنيين في الجامعة لتصبح 250 دولاراً أمريكياً للساعة المعتمدة الواحدة بدلاً من 150 دولاراً، ويطبق القرار على الطلبة المقبولين اعتباراً من بدء العام الجامعي 2012/2013.",
 "كم صارت رسوم الساعة المعتمدة لغير الأردنيين في الدراسات العليا بعد قرار مجلس الأمناء 2012؟","من أي عام يطبق رفع رسوم الساعة لغير الأردنيين إلى 250 دولاراً؟","كم سعر الساعة لغير الأردني بالماجستير؟"),
("rule",[4],"قرار مجلس الأمناء (رسوم البنش لطلبة الماجستير في العلوم الجنائية والسموم)","أضاف مجلس الأمناء رسوماً إضافية لاستعمال الأجهزة والأدوات المخبرية لطلبة برنامج ماجستير العلوم الجنائية والسموم وطلبة الاختصاص العالي في الطب تخصص الطب الشرعي وعلم الأمراض: لغير الأردنيين 2000 دولار أمريكي للعام الجامعي الواحد.",
 "كم الرسوم الإضافية لغير الأردنيين في ماجستير العلوم الجنائية والسموم؟","كم رسوم الاستعمال المخبري للطب الشرعي وعلم الأمراض لغير الأردنيين؟","شو الرسوم الإضافية للطب الشرعي لغير الأردني؟"),
("rule",[4],"قرار مجلس الأمناء (رسوم الاختصاص العالي في طب الأسنان)","حددت الرسوم الجامعية لبرنامج الاختصاص العالي في طب الأسنان لكافة التخصصات: للأردنيين 60 ديناراً للساعة المعتمدة، ورسوم مستلزمات تدريب عملي (Bench Fees) 1500 دينار لكل فصل دراسي ونصف المبلغ (750 ديناراً) للفصل الصيفي. ولغير الأردنيين 150 دولاراً للساعة المعتمدة، و5000 دولار لكل فصل دراسي ونصف المبلغ (2500 دولار) للصيفي.",
 "كم رسوم الاختصاص العالي في طب الأسنان للأردنيين وغير الأردنيين؟","كم رسوم البنش للفصل الصيفي في الاختصاص العالي بطب الأسنان؟","كم أدفع بنش فيز بالصيفي بالاختصاص العالي؟"),
("rule",[5],"قرار مجلس الأمناء (جراحة الفم والوجه والفكين)","بالنسبة لتخصص جراحة الفم والوجه والفكين، ولأن الدراسة سنوية، تعتمد السنة الواحدة بما يعادل 15 ساعة معتمدة. للأردنيين: 60 ديناراً للساعة، ورسوم مستلزمات تدريب عملي 3750 ديناراً لكل سنة دراسية. ولغير الأردنيين: 150 دولاراً للساعة (ثم 250 بعد التعديل)، و12500 دولار لكل سنة دراسية.",
 "كم رسوم الساعة والـ Bench Fees في تخصص جراحة الفم والوجه والفكين؟","كم ساعة تعادل السنة الواحدة في جراحة الفم والوجه والفكين؟","رسوم سنة جراحة الفم والوجه للأردني وغير الأردني كم؟"),
("rule",[5],"قرار مجلس الأمناء (2002/5) توضيح رسوم الأجهزة والأدوات المخبرية","وضح مجلس الأمناء الرسوم الإضافية بدل استعمال الأجهزة والأدوات المخبرية لطلبة الماجستير في كلية طب الأسنان، والاختصاص العالي في الطب الشرعي وعلم الأمراض في كلية الطب، وبرامج الدراسات العليا في الكليات الأخرى التي تتطلب مواد وأجهزة وتجهيزات ذات تكلفة إضافية. فطلبة طب الأسنان الأردنيون 750 ديناراً للفصل الواحد (الأول أو الثاني) وغير الأردنيين 3500 دولار للفصل؛ وطلبة الاختصاص العالي في الطب الشرعي وعلم الأمراض غير الأردنيين 2000 دولار للعام الجامعي الواحد؛ وطلبة بقية الكليات غير الأردنيين 2000 دولار للفصل الواحد. ويعتمد النظام السنوي في الاختصاص العالي ولا يمكن استيفاء الرسوم فصلياً.",
 "ما الرسوم الإضافية لاستعمال الأجهزة والأدوات المخبرية حسب توضيح مجلس الأمناء 2002 لطلبة طب الأسنان وبقية الكليات؟","كم يدفع غير الأردني في الاختصاص العالي بالطب الشرعي بدل الأدوات المخبرية؟","كم رسوم الأجهزة لطلبة الماجستير بالكليات التي بدها تجهيزات؟"),
("rule",[5],"قرار مجلس التعليم العالي (التوفل قبل الامتحان الموحد)","وافق مجلس التعليم العالي على السماح للطلبة الملتحقين حالياً في برامج الدراسات العليا في الجامعات الأردنية قبل قرار المجلس بتاريخ 2010/1/26 بتقديم الامتحان الموحد بدل التوفل الذي تعقده الوزارة، بعد دراستهم المواد المقررة لهذه الغاية.",
 "هل يسمح للملتحقين قبل قرار 2010/1/26 بالامتحان الموحد بدل التوفل؟","ماذا يفعل الطالب الملتحق قبل القرار إذا ما أجتاز التوفل؟","بقدر أقدم الامتحان الموحد بدل التوفل؟"),
("rule",[5],"قرار مجلس التعليم العالي (ذوو الإعاقة، الدراسة الصيفية، القبالة)","منح مجلس التعليم العالي طلبة الدراسات العليا ذوي الإعاقة الملتحقين في الجامعات الأردنية خصماً يصل إلى 90% من رسوم الساعات المعتمدة بدلاً من 50%. ووافق على طرح مواد دراسية لطلبة الدراسات العليا في الفصل الصيفي بالجامعات الأردنية. ووافق مجلس العمداء على قبول أطباء في برنامج الاختصاص العالي في تخصص التخدير والإنعاش ممن يحملون درجة البكالوريوس في الطب والجراحة وتقديرهم أقل من «جيد» نظراً لضعف الإقبال.",
 "كم نسبة خصم رسوم الساعات لطلبة الدراسات العليا ذوي الإعاقة؟","هل يقبل الأطباء بتقدير أقل من جيد في اختصاص التخدير والإنعاش؟","كم الخصم لطالب دراسات عليا من ذوي الإعاقة؟"),
("rule",[6],"قرار مجلس التعليم العالي (الدبلوم العالي في القبالة، IBT وITP)","وافق مجلس التعليم العالي على اعتماد الامتحان الموحد للغة الإنجليزية كامتحان معتمد لغايات القبول في برامج الدراسات العليا في الجامعات الأردنية إلى جانب الامتحانات الأخرى المعتمدة (IBT وITP وIELTS)، ووافق على إنشاء برنامج الدبلوم العالي في القبالة في كلية التمريض، وبالنسبة لحاملي البكالوريوس بتقدير «مقبول» يدرسون 3 مواد من مواد الدبلوم العالي (خلال الفصل الأول) موحدة، وينجحون بمعدل لا يقل عن 70% وبمعدل تراكمي لا يقل عن 75% وتحسب ضمن خطتهم.",
 "ما شرط قبول حامل البكالوريوس بتقدير مقبول في الدبلوم العالي في القبالة؟","ما الامتحانات المعتمدة للغة الإنجليزية لغايات القبول في الدراسات العليا حسب مجلس التعليم العالي؟","أنا تقديري مقبول، كيف بنقبل بدبلوم القبالة؟"),
("rule",[6],"قرار مجلس التعليم العالي (الحاصلون على شهادات بالانتساب)","عدل مجلس التعليم العالي قراريه الخاصين بالطلبة الحاصلين على الشهادات الجامعية بالانتساب بإلغاء شرط دراسة (30) ساعة للبكالوريوس و(15) ساعة للدكتوراه لغايات المعادلة في الوزارة، وعلى النحو التالي: يسمح للحاصلين على الماجستير بالانتساب بالالتحاق ببرامج الدكتوراه في الجامعات الأردنية أو التقدم بطلبات لمعادلة شهاداتهم بشرط دراسة ساعات لا تقل عن 15 ساعة معتمدة في الجامعات الرسمية فقط من المواد المعدة لاستكمال الماجستير وفي مجال التخصص والنجاح فيها بمعدل لا يقل عن 75% أو ما يعادله.",
 "ما شرط التحاق الحاصل على الماجستير بالانتساب ببرامج الدكتوراه؟","كم ساعة يدرس حامل الماجستير بالانتساب لمعادلة شهادته أو الالتحاق بالدكتوراه؟","ماجستيري انتساب وبدي دكتوراه، شو بدي أعمل؟"),
("rule",[6],"قرار مجلس التعليم العالي (2010/12/16) خريجو البكالوريوس بالانتساب","يسمح للحاصلين على بكالوريوس بالانتساب بالتقدم بطلبات الالتحاق ببرامج الدراسات العليا في الجامعات الرسمية أو الخاصة اعتباراً من الفصل الأول 2011/2012 بشرط: دراسة برنامج تأهيلي لا يقل عن 30 ساعة معتمدة بالجامعات الرسمية فقط وحسب طاقاتها الاستيعابية في البرنامج الموازي، وأن تكون المواد حسب تخصص البكالوريوس وفي مواد التخصص البحتة وبمعدل تراكمي لا يقل عن 70% ويشترط النجاح في كافة المواد. ويمكن للناجحين التقدم لبرامج الماجستير في الجامعات الرسمية أو الخاصة، ويستثنى الحاصل على معدل (مقبول) من دراسة المواد الثلاث الأخرى.",
 "ما شروط التحاق خريجي البكالوريوس بالانتساب بالدراسات العليا بعد 2011/2012؟","كم ساعة البرنامج التأهيلي لخريجي الانتساب وما المعدل المطلوب؟","خريج انتساب، كيف بقدر أعمل ماجستير؟"),
("rule",[7],"قرارات مجلس التعليم العالي (التوفل شرط قبول لغير الأردنيين، المحاولة الواحدة)","وافق مجلس التعليم العالي على ألا يكون التوفل شرطاً للقبول للطلبة غير الأردنيين، وفي حال عدم تحقيق الحد الأدنى للنجاح في الامتحان تقديم الإمتحان لمرة واحدة على الأقل في تخصص مادتين من اللغة الإنجليزية، وفي نهاية الأمر يخضع للامتحان الموحد الذي تعقده الوزارة قبل إنهاء الفصل الأول أو الامتحان الموحد خلال السنة الأولى. ووافق على السماح لطلبة الدراسات العليا (ماجستير ودكتوراه) الذين لم يحققوا النجاح في التوفل بمرة واحدة (بدلاً من مرتين) بدراسة مساقات اللغة الإنجليزية مع مراعاة اجتياز التوفل أو الامتحان الموحد خلال الفصل الأول من التسجيل أو السنة الأولى، وأن يكون اجتياز التوفل اختيارياً للطلبة الوافدين في التخصصات الإنسانية والاجتماعية اعتباراً من 2008/2009.",
 "هل التوفل شرط قبول لطلبة الدراسات العليا غير الأردنيين؟","كم محاولة توفل تلزم قبل السماح بدراسة مساقات الإنجليزية للماجستير والدكتوراه حسب قرار 2008/2009؟","التوفل اختياري للوافدين في التخصصات الإنسانية؟"),
("rule",[7],"قرارات مجلس العمداء ومجلس التعليم العالي (معايير القبول، الاعتراف، العنف الطلابي)","يصدر مجلس العمداء سنوياً معايير وأسساً للقبول في الدراسات العليا حسب أعداد المتقدمين وتخصص البكالوريوس والمقابلات الشخصية ونسبة مئوية للجامعة وغيرها. ووافق مجلس التعليم العالي على استثناء الطلبة غير الأردنيين من شرط الاعتراف المسبق بالجامعات التي تخرجوا منها ومعادلة شهاداتهم لغايات الالتحاق ببرامج الدراسات العليا في الجامعات الأردنية شريطة اعتراف دولهم بتلك الجامعات. وقرر عدم الموافقة على قبول الطلبة المفصولين من أي جامعة أردنية بسبب قضايا العنف الطلابي طيلة فترة العقوبة كحد أدنى.",
 "هل يقبل في الدراسات العليا الطالب المفصول من جامعة أردنية بسبب العنف الطلابي؟","ما الاستثناء الذي حصل عليه الطلبة غير الأردنيين فيما يخص الاعتراف بالجامعات؟","مين بحدد معايير القبول بالدراسات العليا كل سنة؟"),
("rule",[7],"قرار مجلس أمناء الجامعة (رسوم الخدمات التكنولوجية)","عدل مجلس الأمناء قراره الخاص برسوم الخدمات التكنولوجية، فيطبق القرار على طلبة برنامج الاختصاص العالي اعتباراً من بدء الفصل الصيفي للعام 2011/2012، وتكون رسوم الخدمات التكنولوجية التي تدفع من قبلهم عن ثلاثة فصول دراسية تدفع مرة واحدة مع الرسوم في الفصل الصيفي من كل عام. وتستوفى الرسوم الجامعية من الطلبة غير الأردنيين بالدولار الأمريكي.",
 "متى تدفع رسوم الخدمات التكنولوجية لطلبة الاختصاص العالي وعن كم فصل؟","بأي عملة تستوفى الرسوم الجامعية من الطلبة غير الأردنيين في الدراسات العليا؟","رسوم الخدمات التكنولوجية بالاختصاص العالي كيف بتتدفع؟"),
("rule",[8],"قرار مجلس الأمناء (2011/2012) رسوم الخدمات التكنولوجية","عدل مجلس الأمناء قراره الخاص بالرسوم بحيث تصبح رسوم الخدمات التكنولوجية 25 ديناراً لكل طالب في البرنامج العادي، و75 ديناراً لطلبة البرنامج الموازي وطلبة الدراسات العليا عن كل فصل دراسي بما فيها الفصل الصيفي، وتعديل مسماها إلى «خدمات تكنولوجية»، وتطبق على المقبولين اعتباراً من بدء العام الجامعي 2011/2012.",
 "كم رسوم الخدمات التكنولوجية للبرنامج العادي والموازي والدراسات العليا لكل فصل؟","ما الاسم الجديد لرسوم استخدام الحاسوب بعد تعديل مجلس الأمناء؟","كم بدفع خدمات تكنولوجية وأنا موازي؟"),
("rule",[8],"قرارات مجلس العمداء والتعليم العالي (2012–2015)","وافق مجلس التعليم العالي على طرح مواد دراسية لطلبة الدراسات العليا في الفصل الصيفي بالجامعات الأردنية، ولا مانع لدى الوزارة من قبول طلبة في الجامعة في برامج الماجستير في الفصل الصيفي وفق أسس القبول. وقرر مجلس العمداء استحداث تخصص هندسة الطاقة المتجددة والتنمية المستدامة ضمن برنامج الهندسة الميكاترونية بكلية الهندسة من العام الجامعي 2012/2013، واعتماد امتحان التوفل الورقي (PBT) لتحقيق شرط القبول لطلبة الدراسات العليا لأن وزارة التعليم العالي لم تشر إلى عدم اعتماده، والموافقة على إعادة فتح مسار الامتحان الشامل ضمن برنامج الماجستير في الكليات المعنية بالدراسات العليا في الجامعة اعتباراً من العام 2014/2015.",
 "هل يعتمد التوفل الورقي PBT لشرط القبول في الدراسات العليا؟","ما التخصص الجديد الذي استحدث ضمن الهندسة الميكاترونية في 2012/2013؟","متى أعيد فتح مسار الامتحان الشامل في الماجستير؟"),
("rule",[8],"قرار مجلس العمداء (إعادة رسوم المساق، 2014/2015)","اعتمد مجلس العمداء آلية لرسوم طلبة الدراسات العليا الحاصلين على منح تشغيلية (إعادة رسوم الفصل): تذميم رسوم ساعات المساق الذي يرسب فيه الطالب أو يقوم بتسجيله (بحسب نص القرار)، وبخصوص الطلبة غير الأردنيين تعاد رسوم الساعات بما يعادل رسوم الساعات للطالب الأردني لنفس التخصص. ويطبق القرار اعتباراً من الفصل الدراسي الثاني 2014/2015.",
 "كيف تعاد رسوم الفصل لطلبة الدراسات العليا الحاصلين على منح تشغيلية؟","ماذا يحدث لرسوم الساعات لغير الأردني الحاصل على منحة تشغيلية في الدراسات العليا؟","منحة تشغيلية، كيف بترجعلي الرسوم؟"),
("rule",[8],"قرار مجلس العمداء (غرامة التأخير، 2015/2016)","قرر مجلس العمداء استيفاء مبلغ 100 دينار (غرامة تأخير) من الطلبة الذين يتأخرون في تقديم طلبات تأجيل أو تمديد الدراسة بعد الموعد المحدد، ويطبق القرار اعتباراً من بدء العام الجامعي 2015/2016 على طلبة الدراسات العليا.",
 "كم غرامة التأخير في طلب تأجيل أو تمديد الدراسة لطلبة الدراسات العليا؟","من أي عام تطبق غرامة 100 دينار على طلبات التأجيل المتأخرة؟","تأخرت بطلب التأجيل، كم الغرامة؟"),
("rule",[8],"قرارات مجلس العمداء (مناقشة الرسائل، الصيدلة التكنولوجية)","أقر مجلس العمداء أسساً لإبراز المظهر العام لبرامج الدراسات العليا وإخراجها بأفضل صورة عبر مواقع التواصل الاجتماعي وقناة الجامعة (Y-Tube): التزام كل من لجنة المناقشة والطالب بارتداء الأرواب الجامعية أثناء مناقشة الرسالة، وتصوير المناقشة بشكل موحد لجميع المناقشات التي تحددها كلية الدراسات العليا، والتزام كل كلية علمية تطرح برامج دراسات عليا بتهيئة قاعات مناسبة لمناقشة الرسائل الجامعية خلال العام الدراسي. وقرر تفعيل برنامج الدكتوراه في الصيدلة التكنولوجية اعتباراً من الفصل الثاني للعام 2016/2017.",
 "ما الشروط التي أقرها مجلس العمداء لمناقشة الرسائل من حيث الأرواب والتصوير؟","متى فعل برنامج الدكتوراه في الصيدلة التكنولوجية؟","هل لازم ألبس روب بمناقشة الرسالة؟"),
("rule",[9],"قرارات مجلس العمداء (المصدقة الجامعية، مكافأة الممتحن الخارجي، 2017/2018)","عدل مجلس العمداء المصدقة الجامعية لطلبة الدراسات العليا باستبدال عبارة «تشهد وحدة القبول والتسجيل أن مجلس العمداء قرر» بعبارة «استناداً إلى قرار مجلس العمداء في جلسته رقم ( ) بتاريخ»، وتمنح الدرجة من كلية الدراسات العليا وليس من كلية التخصص الأصيل. وعدل قرار مكافأة الممتحن الخارجي بحيث تصرف مكافأة لعضو لجنة مناقشة الرسائل بواقع 100 دينار أردني إن كان العضو من خارج الجامعة فقط، ويطبق اعتباراً من العام الجامعي 2017/2018.",
 "كم مكافأة عضو لجنة مناقشة الرسالة القادم من خارج الجامعة؟","من أي كلية تمنح درجة الماجستير بعد قرار تعديل المصدقة الجامعية؟","شو بتغير بصيغة المصدقة الجامعية لطلبة الدراسات العليا؟"),
("rule",[9],"قرار مجلس الأمناء (رسوم الماجستير 2017/2018)","حدد مجلس الأمناء رسوم الساعة المعتمدة لبرامج الماجستير اعتباراً من العام الجامعي 2017/2018: الهندسة الطبية الحيوية (كلية الهندسة) 120 ديناراً للأردنيين و500 دولار لغير الأردنيين، وهندسة وعلوم النانو (معهد النانوتكنولوجي) 120 ديناراً للأردنيين و500 دولار لغير الأردنيين.",
 "كم رسوم الساعة لماجستير الهندسة الطبية الحيوية وهندسة وعلوم النانو؟","كم يدفع غير الأردني في ماجستير النانوتكنولوجي للساعة؟","كم سعر الساعة بماجستير النانو؟"),
("rule",[9],"قرار مجلس العمداء (المنح التدريسية لخريجي البكالوريوس المتفوقين)","وافق مجلس العمداء على شمول الطلبة الذين ينهون متطلبات الحصول على درجة البكالوريوس قبل نهاية الفوج ومعدلهم التراكمي أعلى أو يوازي الأول على الفوج السابق بالمنح التدريسية لطلبة الدراسات العليا، وبغض النظر عن الفصل الدراسي الذي ينهي به الطالب متطلبات الحصول على البكالوريوس.",
 "من يشمل بالمنح التدريسية لطلبة الدراسات العليا من خريجي البكالوريوس قبل نهاية الفوج؟","هل يشترط أن يتخرج الطالب في فصل معين ليحصل على المنحة التدريسية؟","خلصت البكالوريوس بدري ومعدلي عالي، بنطيني منحة؟"),
],"a2",verified="image")
